export interface ConnectorConfig {
  /** Zendesk subdomain (e.g., "mycompany" for mycompany.zendesk.com) */
  zendeskSubdomain: string
  /** Zendesk API access token (from ZENDESK_ACCESS_TOKEN env var) */
  zendeskAccessToken: string
  /** Intercom App ID used to construct conversation URLs */
  intercomAppId: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface IntercomWebhookPayload {
  type: string
  topic: string
  data: {
    item: {
      type: string
      id: string
      url?: string
    }
  }
}

export interface HandleResult {
  ticketId: number
  subject: string
  description: string
}

const EXPECTED_TOPIC = 'conversation_part.tag.created'
const EXPECTED_ITEM_TYPE = 'conversation'

function buildConversationUrl(appId: string, conversationId: string): string {
  return `https://app.intercom.com/a/apps/${appId}/inbox/all/conversations/${conversationId}`
}

function validatePayload(payload: unknown): asserts payload is IntercomWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (p.type !== 'notification_event') {
    throw new Error(`Expected type "notification_event", got "${p.type}"`)
  }
  if (p.topic !== EXPECTED_TOPIC) {
    throw new Error(`Expected topic "${EXPECTED_TOPIC}", got "${p.topic}"`)
  }
  if (!p.data || typeof p.data !== 'object') {
    throw new Error('Missing "data" object')
  }
  const data = p.data as Record<string, unknown>
  if (!data.item || typeof data.item !== 'object') {
    throw new Error('Missing "data.item" object')
  }
  const item = data.item as Record<string, unknown>
  if (item.type !== EXPECTED_ITEM_TYPE) {
    throw new Error(`Expected item type "${EXPECTED_ITEM_TYPE}", got "${item.type}"`)
  }
  if (!item.id || typeof item.id !== 'string') {
    throw new Error('Missing or invalid "data.item.id" (string required)')
  }
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const typedPayload = payload as IntercomWebhookPayload

  const conversationId = typedPayload.data.item.id
  const conversationUrl = buildConversationUrl(config.intercomAppId, conversationId)
  const description = `Intercom conversation ID: ${conversationId}`

  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`
  const requestBody = {
    ticket: {
      subject: conversationUrl,
      comment: {
        body: description
      }
    }
  }

  const fetchImpl = config.fetch ?? fetch
  const response = await fetchImpl(zendeskUrl, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.zendeskAccessToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(requestBody)
  })

  if (!response.ok) {
    throw new Error(`Zendesk API error: ${response.status} ${response.statusText} for POST ${zendeskUrl}`)
  }

  const result = await response.json() as { ticket: { id: number } }
  return {
    ticketId: result.ticket.id,
    subject: conversationUrl,
    description
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, IntercomWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      zendeskSubdomain: 'testsubdomain',
      zendeskAccessToken: 'test-token',
      intercomAppId: 'test-app-id',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.ticketId).toBe(12345)
    expect(result.subject).toBe('https://app.intercom.com/a/apps/test-app-id/inbox/all/conversations/12345')
    expect(result.description).toBe('Intercom conversation ID: 12345')
  })
})

describe('handle', () => {
  it('creates a Zendesk ticket with correct field mapping on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://mysub.zendesk.com/api/v2/tickets.json')
      expect(req.headers.get('authorization')).toBe('Bearer secret-token')
      expect(req.json).toEqual({
        ticket: {
          subject: 'https://app.intercom.com/a/apps/my-app/inbox/all/conversations/67890',
          comment: { body: 'Intercom conversation ID: 67890' }
        }
      })
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '67890'
        }
      }
    }

    const config: ConnectorConfig = {
      zendeskSubdomain: 'mysub',
      zendeskAccessToken: 'secret-token',
      intercomAppId: 'my-app',
      fetch
    }

    const result = await handle(payload, config)
    expect(result.ticketId).toBe(12345)
    expect(calls.length).toBe(1)
  })

  it('throws descriptive error when required field data.item.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: { item: { type: 'conversation' } }
    }
    const config: ConnectorConfig = {
      zendeskSubdomain: 'sub',
      zendeskAccessToken: 'tok',
      intercomAppId: 'app',
      fetch
    }
    await expect(handle(payload as unknown as IntercomWebhookPayload, config))
      .rejects.toThrow('Missing or invalid "data.item.id"')
  })

  it('throws descriptive error when topic is unexpected', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.removed',
      data: { item: { type: 'conversation', id: '123' } }
    }
    const config: ConnectorConfig = {
      zendeskSubdomain: 'sub',
      zendeskAccessToken: 'tok',
      intercomAppId: 'app',
      fetch
    }
    await expect(handle(payload as unknown as IntercomWebhookPayload, config))
      .rejects.toThrow('Expected topic "conversation_part.tag.created"')
  })

  it('throws error with status and endpoint on non-2xx Zendesk response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: { item: { type: 'conversation', id: '111' } }
    }
    const config: ConnectorConfig = {
      zendeskSubdomain: 'sub',
      zendeskAccessToken: 'bad-token',
      intercomAppId: 'app',
      fetch
    }
    await expect(handle(payload, config))
      .rejects.toThrow('Zendesk API error: 401 Unauthorized for POST https://sub.zendesk.com/api/v2/tickets.json')
  })

  it('uses injected fetch instead of global fetch', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response))
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: { item: { type: 'conversation', id: '999' } }
    }
    const config: ConnectorConfig = {
      zendeskSubdomain: 'sub',
      zendeskAccessToken: 'tok',
      intercomAppId: 'app',
